// Melody-driven music system
const MELODY_NOTES = [
  // C minor pentatonic phrases
  [262, 311, 349, 392, 466, 523],  // C4, Eb4, F4, G4, Bb4, C5
  [196, 233, 262, 311, 349, 392],  // G3, Bb3, C4, Eb4, F4, G4
];

const BASS_NOTES = [65, 73, 87, 98]; // C2, D2, F2, G2

let musicNodes: { osc: OscillatorNode; gain: GainNode }[] = [];
let musicTimer: ReturnType<typeof setInterval> | null = null;
let musicPlaying = false;
let melodyStep = 0;
let bassStep = 0;

function playMelodyNote() {
  if (!gameState.musicEnabled || !musicPlaying) return;
  try {
    const c = getCtx();
    const wave = Math.min(gameState.wave, MELODY_NOTES.length) - 1;
    const notes = MELODY_NOTES[Math.max(0, wave)] ?? MELODY_NOTES[0];
    const freq = notes[melodyStep % notes.length];
    const dur = 0.15 + Math.random() * 0.1;

    const o = c.createOscillator();
    const g = c.createGain();
    o.type = 'triangle';
    o.frequency.setValueAtTime(freq, c.currentTime);
    g.gain.setValueAtTime(0.04, c.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, c.currentTime + dur);
    o.connect(g).connect(c.destination);
    o.start();
    o.stop(c.currentTime + dur);

    melodyStep++;
    // Every 4th note, play bass
    if (melodyStep % 4 === 0) {
      const bassFreq = BASS_NOTES[bassStep % BASS_NOTES.length];
      const bo = c.createOscillator();
      const bg = c.createGain();
      bo.type = 'sine';
      bo.frequency.setValueAtTime(bassFreq, c.currentTime);
      bg.gain.setValueAtTime(0.05, c.currentTime);
      bg.gain.exponentialRampToValueAtTime(0.001, c.currentTime + 0.4);
      bo.connect(bg).connect(c.destination);
      bo.start();
      bo.stop(c.currentTime + 0.4);
      bassStep++;
    }
  } catch {}
}

function startMusic() {
  if (musicPlaying || !gameState.musicEnabled) return;
  try {
    const c = getCtx();
    // Low ambient drone
    const droneOsc = c.createOscillator();
    const droneGain = c.createGain();
    droneOsc.type = 'sine';
    droneOsc.frequency.setValueAtTime(55, c.currentTime);
    droneGain.gain.setValueAtTime(0.03, c.currentTime);
    droneOsc.connect(droneGain).connect(c.destination);
    droneOsc.start();
    musicNodes.push({ osc: droneOsc, gain: droneGain });

    // Second drone a fifth up
    const droneOsc2 = c.createOscillator();
    const droneGain2 = c.createGain();
    droneOsc2.type = 'sine';
    droneOsc2.frequency.setValueAtTime(82, c.currentTime);
    droneGain2.gain.setValueAtTime(0.02, c.currentTime);
    droneOsc2.connect(droneGain2).connect(c.destination);
    droneOsc2.start();
    musicNodes.push({ osc: droneOsc2, gain: droneGain2 });

    // Melody timer — notes every ~300ms
    const tempo = 300;
    musicTimer = setInterval(playMelodyNote, tempo);
    musicPlaying = true;
  } catch {}
}

function stopMusic() {
  for (const n of musicNodes) {
    try { n.osc.stop(); } catch {}
    try { n.gain.disconnect(); } catch {}
  }
  musicNodes = [];
  if (musicTimer) { clearInterval(musicTimer); musicTimer = null; }
  musicPlaying = false;
  melodyStep = 0;
  bassStep = 0;
}

export class AudioSystem extends createSystem({}) {
  private prevScreen = '';

  init() {}

  update(_delta: number, time: number) {
    // SFX
    if (gameState.sfxAction) {
      const fn = SFX[gameState.sfxAction];
      if (fn) fn();
      gameState.sfxAction = '';
    }
    // Music
    if (gameState.screen === 'playing' && gameState.musicEnabled) {
      if (!musicPlaying) startMusic();
      // Modulate drone frequency based on wave intensity
      if (musicNodes.length > 0) {
        const baseFreq = 55 + gameState.wave * 2;
        const mod = Math.sin(time * 0.3) * 5;
        try {
          musicNodes[0].osc.frequency.setValueAtTime(baseFreq + mod, getCtx().currentTime);
        } catch {}
      }
    } else if (musicPlaying) {
      stopMusic();
    }
    if (gameState.screen === 'gameover' && this.prevScreen === 'playing') {
      SFX.gameover?.();
    }
    this.prevScreen = gameState.screen;
  }
}

// Neon Joust VR — Effects system (particles + ambient + wave transitions + lava embers)
import { createSystem, World, Group, Mesh, SphereGeometry, BoxGeometry, MeshBasicMaterial,
  LineSegments, EdgesGeometry, LineBasicMaterial } from '@iwsdk/core';
import { gameState, COLOR_SCHEMES, POWERUP_COLORS, ARENA_W, LAVA_Y } from './game-state.js';

interface Particle { mesh: Mesh; vx: number; vy: number; vz: number; life: number; maxLife: number; }
interface Orb { mesh: Mesh; baseY: number; speed: number; phase: number; }
interface Ember { mesh: Mesh; x: number; y: number; vx: number; vy: number; life: number; wobble: number; }

export class EffectsSystem extends createSystem({}) {

  private particles: Particle[] = [];
  private orbs: Orb[] = [];
  private embers: Ember[] = [];
  private prevScore = 0;
  private prevWave = 0;
  private prevPowerUp: string | null = null;
  private emberTimer = 0;
  private prevPlayerAlive = true;
  private respawnFlashTimer = 0;
  private flashMesh: Mesh | null = null;
  private deathBurstDone = false;

  init() {
    this.createOrbs();
    this.createFlashOverlay();
  }

  private createOrbs() {
    const scene = this.world.scene;
    for (let i = 0; i < 20; i++) {
      const geo = new SphereGeometry(0.06 + Math.random() * 0.04, 6, 4);
      const mat = new MeshBasicMaterial({ color: gameState.accentColor, transparent: true, opacity: 0.3 + Math.random() * 0.3 });
      const mesh = new Mesh(geo, mat);
      const x = (Math.random() - 0.5) * 24;
      const y = 1 + Math.random() * 13;
      const z = -2 + Math.random() * 4;
      mesh.position.set(x, y, z);
      scene.add(mesh);
      this.orbs.push({ mesh, baseY: y, speed: 0.2 + Math.random() * 0.4, phase: Math.random() * Math.PI * 2 });
    }
  }

  private createFlashOverlay() {
    // Full-screen flash for big events (boss defeat, death, respawn)
    const geo = new BoxGeometry(50, 30, 0.01);
    const mat = new MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0 });
    this.flashMesh = new Mesh(geo, mat);
    this.flashMesh.position.set(0, 7, 15);
    this.world.scene.add(this.flashMesh);
  }

  private triggerFlash(color: number, intensity: number) {
    if (!this.flashMesh) return;
    (this.flashMesh.material as MeshBasicMaterial).color.setHex(color);
    (this.flashMesh.material as MeshBasicMaterial).opacity = intensity;
  }

  burst(x: number, y: number, color: number, count: number = 8) {
    for (let i = 0; i < count; i++) {
      const geo = new SphereGeometry(0.04, 4, 3);
      const mat = new MeshBasicMaterial({ color, transparent: true, opacity: 0.8 });
      const mesh = new Mesh(geo, mat);
      mesh.position.set(x, y, 0);
      this.world.scene.add(mesh);
      const angle = (Math.PI * 2 * i) / count;
      const spd = 2 + Math.random() * 3;
      this.particles.push({
        mesh, vx: Math.cos(angle) * spd, vy: Math.sin(angle) * spd,
        vz: (Math.random() - 0.5) * 2, life: 0.6 + Math.random() * 0.4, maxLife: 1.0,
      });
    }
  }

  private deathExplosion(x: number, y: number) {
    // Large burst with player color and white sparks
    this.burst(x, y, gameState.accentColor, 20);
    this.burst(x, y, 0xffffff, 10);
    // Outward ring of larger particles
    for (let i = 0; i < 12; i++) {
      const geo = new SphereGeometry(0.06, 4, 3);
      const mat = new MeshBasicMaterial({ color: 0xff4444, transparent: true, opacity: 0.9 });
      const mesh = new Mesh(geo, mat);
      mesh.position.set(x, y, 0);
      this.world.scene.add(mesh);
      const angle = (Math.PI * 2 * i) / 12;
      const spd = 5 + Math.random() * 3;
      this.particles.push({
        mesh, vx: Math.cos(angle) * spd, vy: Math.sin(angle) * spd,
        vz: (Math.random() - 0.5) * 3, life: 0.8 + Math.random() * 0.4, maxLife: 1.2,
      });
    }
    // Falling debris particles
    for (let i = 0; i < 8; i++) {
      const geo = new BoxGeometry(0.05, 0.05, 0.05);
      const mat = new MeshBasicMaterial({ color: gameState.accentColor, transparent: true, opacity: 0.7 });
      const mesh = new Mesh(geo, mat);
      mesh.position.set(x, y, 0);
      this.world.scene.add(mesh);
      this.particles.push({
        mesh,
        vx: (Math.random() - 0.5) * 6,
        vy: 2 + Math.random() * 5,
        vz: (Math.random() - 0.5) * 2,
        life: 1.0 + Math.random() * 0.5,
        maxLife: 1.5,
      });
    }
    this.triggerFlash(0xff4444, 0.15);
  }

  private respawnSparkle(x: number, y: number) {
    // Upward spiral of sparkles at respawn point
    for (let i = 0; i < 16; i++) {
      const geo = new SphereGeometry(0.03, 4, 3);
      const mat = new MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.9 });
      const mesh = new Mesh(geo, mat);
      mesh.position.set(x, y - 0.5, 0);
      this.world.scene.add(mesh);
      const angle = (Math.PI * 2 * i) / 16;
      const radius = 0.3 + (i / 16) * 0.5;
      this.particles.push({
        mesh,
        vx: Math.cos(angle) * radius * 3,
        vy: 3 + Math.random() * 4,
        vz: Math.sin(angle) * radius,
        life: 0.6 + Math.random() * 0.4,
        maxLife: 1.0,
      });
    }
    // Central glow burst
    this.burst(x, y, gameState.accentColor, 8);
    this.triggerFlash(gameState.accentColor, 0.1);
    this.respawnFlashTimer = 0.5;
  }

  private spawnEmber() {
    const x = (Math.random() - 0.5) * (ARENA_W + 2);
    const geo = new SphereGeometry(0.025 + Math.random() * 0.02, 4, 3);
    const colors = [0xff4400, 0xff6600, 0xff8800, 0xffaa00];
    const color = colors[Math.floor(Math.random() * colors.length)];
    const mat = new MeshBasicMaterial({ color, transparent: true, opacity: 0.5 + Math.random() * 0.3 });
    const mesh = new Mesh(geo, mat);
    mesh.position.set(x, LAVA_Y + 0.2, (Math.random() - 0.5) * 3);
    this.world.scene.add(mesh);
    this.embers.push({
      mesh, x, y: LAVA_Y + 0.2,
      vx: (Math.random() - 0.5) * 0.5,
      vy: 0.8 + Math.random() * 1.5,
      life: 1.5 + Math.random() * 2,
      wobble: Math.random() * Math.PI * 2,
    });
  }

  private trailBurst(x: number, y: number, color: number) {
    for (let i = 0; i < 4; i++) {
      const geo = new SphereGeometry(0.03, 4, 3);
      const mat = new MeshBasicMaterial({ color, transparent: true, opacity: 0.6 });
      const mesh = new Mesh(geo, mat);
      mesh.position.set(x, y, 0);
      this.world.scene.add(mesh);
      this.particles.push({
        mesh, vx: (Math.random() - 0.5) * 1.5, vy: 3 + Math.random() * 4,
        vz: (Math.random() - 0.5), life: 0.5 + Math.random() * 0.3, maxLife: 0.8,
      });
    }
  }

  private waveTransitionEffect() {
    for (let i = 0; i < 5; i++) {
      const x = (Math.random() - 0.5) * 18;
      const y = 2 + Math.random() * 10;
      this.burst(x, y, gameState.accentColor, 15);
    }
    // Firework trails from bottom
    for (let i = 0; i < 3; i++) {
      const x = -6 + i * 6;
      for (let j = 0; j < 8; j++) {
        const geo = new SphereGeometry(0.05, 4, 3);
        const hue = [0xff4444, 0x44ff44, 0x4444ff, 0xffcc00, 0xff44ff, 0x00ffff, 0xff8800, 0xffffff];
        const mat = new MeshBasicMaterial({ color: hue[j % hue.length], transparent: true, opacity: 0.9 });
        const mesh = new Mesh(geo, mat);
        mesh.position.set(x, 1, 0);
        this.world.scene.add(mesh);
        const angle = (Math.PI * 2 * j) / 8;
        this.particles.push({
          mesh, vx: Math.cos(angle) * 4, vy: 5 + Math.sin(angle) * 3,
          vz: (Math.random() - 0.5) * 2, life: 1.2, maxLife: 1.2,
        });
      }
    }
    // Boss wave gets extra dramatic
    if (gameState.bossWave) {
      this.triggerFlash(0xff6600, 0.12);
    }
  }

  private bossDefeatExplosion() {
    // Massive multi-burst explosion for boss defeat
    for (let i = 0; i < 3; i++) {
      const bx = gameState.playerX + (Math.random() - 0.5) * 4;
      const by = gameState.playerY + (Math.random() - 0.5) * 4;
      this.burst(bx, by, 0xff6600, 16);
      this.burst(bx, by, 0xffcc00, 10);
    }
    // Big white flash
    this.triggerFlash(0xffcc00, 0.2);
  }

  update(delta: number, time: number) {
    const dt = Math.min(delta, 0.05);

    // Particles
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) {
        this.world.scene.remove(p.mesh);
        this.particles.splice(i, 1);
        continue;
      }
      p.mesh.position.x += p.vx * dt;
      p.mesh.position.y += p.vy * dt;
      p.mesh.position.z += p.vz * dt;
      p.vy -= 5 * dt;
      const mat = p.mesh.material as MeshBasicMaterial;
      mat.opacity = (p.life / p.maxLife) * 0.8;
      p.mesh.scale.setScalar(0.3 + (p.life / p.maxLife) * 0.7);
    }

    // Ambient orbs
    for (const o of this.orbs) {
      o.mesh.position.y = o.baseY + Math.sin(time * o.speed + o.phase) * 0.5;
      const mat = o.mesh.material as MeshBasicMaterial;
      mat.opacity = 0.2 + 0.2 * Math.sin(time * o.speed * 2 + o.phase);
    }

    // Lava embers — continuously rising from lava
    if (gameState.screen === 'playing' || gameState.screen === 'menu') {
      this.emberTimer -= dt;
      if (this.emberTimer <= 0) {
        this.emberTimer = 0.3 + Math.random() * 0.5;
        this.spawnEmber();
        // More embers at higher waves
        if (gameState.wave >= 5 && Math.random() < 0.4) this.spawnEmber();
        if (gameState.wave >= 10 && Math.random() < 0.3) this.spawnEmber();
      }
    }
    for (let i = this.embers.length - 1; i >= 0; i--) {
      const e = this.embers[i];
      e.life -= dt;
      if (e.life <= 0) {
        this.world.scene.remove(e.mesh);
        this.embers.splice(i, 1);
        continue;
      }
      e.y += e.vy * dt;
      e.x += e.vx * dt + Math.sin(time * 3 + e.wobble) * 0.3 * dt;
      e.mesh.position.set(e.x, e.y, e.mesh.position.z);
      const mat = e.mesh.material as MeshBasicMaterial;
      // Fade out near end of life
      mat.opacity = Math.min(0.7, (e.life / 2) * 0.7);
      // Shrink as they rise
      const s = 0.5 + (e.life / 3) * 0.5;
      e.mesh.scale.setScalar(s);
    }

    // Death explosion — trigger once when player dies
    if (!gameState.playerAlive && this.prevPlayerAlive) {
      this.deathExplosion(gameState.playerX, gameState.playerY);
      this.deathBurstDone = true;
    }
    // Respawn sparkle — trigger once when player comes back alive
    if (gameState.playerAlive && !this.prevPlayerAlive) {
      this.respawnSparkle(gameState.playerX, gameState.playerY);
    }
    this.prevPlayerAlive = gameState.playerAlive;

    // Respawn flash fade
    if (this.respawnFlashTimer > 0) {
      this.respawnFlashTimer -= dt;
    }

    // Flash overlay fade
    if (this.flashMesh) {
      const mat = this.flashMesh.material as MeshBasicMaterial;
      if (mat.opacity > 0) {
        mat.opacity = Math.max(0, mat.opacity - dt * 0.8);
      }
    }

    // Score-triggered bursts
    if (gameState.score > this.prevScore + 100) {
      this.burst(gameState.playerX, gameState.playerY, gameState.accentColor, 6);
      this.prevScore = gameState.score;
    }

    // Wave-triggered celebration
    if (gameState.wave > this.prevWave && this.prevWave > 0) {
      this.waveTransitionEffect();
    }
    this.prevWave = gameState.wave;

    // Boss defeat flash (triggered via sfxAction in game-system)
    if (gameState.sfxAction === 'boss_defeat') {
      this.bossDefeatExplosion();
    }

    // Power-up collect effect
    const currentPU = gameState.activePowerUp;
    if (currentPU && currentPU !== this.prevPowerUp) {
      const color = POWERUP_COLORS[currentPU] ?? 0xffffff;
      this.burst(gameState.playerX, gameState.playerY, color, 12);
      for (let i = 0; i < 8; i++) {
        const angle = (Math.PI * 2 * i) / 8;
        const px = gameState.playerX + Math.cos(angle) * 0.8;
        const py = gameState.playerY + Math.sin(angle) * 0.8;
        this.trailBurst(px, py, color);
      }
    }
    this.prevPowerUp = currentPU;

    // Color scheme change — update orb colors
    if (gameState.colorChanged) {
      gameState.colorChanged = false;
      for (const o of this.orbs) {
        (o.mesh.material as MeshBasicMaterial).color.setHex(gameState.accentColor);
      }
    }
  }

  updateOrbColors(color: number) {
    for (const o of this.orbs) {
      (o.mesh.material as MeshBasicMaterial).color.setHex(color);
    }
  }
}

// Neon Joust VR — Input system (keyboard + VR)
import { createSystem, World } from '@iwsdk/core';
import { gameState } from './game-state.js';
import { GameSystem } from './game-system.js';

export class InputSystem extends createSystem({}) {

  private keys: Record<string, boolean> = {};
  private prevFlap = false;

  init() {
    window.addEventListener('keydown', (e) => {
      this.keys[e.key.toLowerCase()] = true;
      if (e.key === 'Escape' || e.key.toLowerCase() === 'p') {
        if (gameState.screen === 'playing') gameState.screen = 'paused';
        else if (gameState.screen === 'paused') gameState.screen = 'playing';
      }
    });
    window.addEventListener('keyup', (e) => { this.keys[e.key.toLowerCase()] = false; });
  }

  update(_delta: number, _time: number) {
    const game = ((this.world as any).getSystem(GameSystem) as GameSystem);
    if (!game) return;
    const left = !!(this.keys['arrowleft'] || this.keys['a']);
    const right = !!(this.keys['arrowright'] || this.keys['d']);
    const flap = !!(this.keys['arrowup'] || this.keys['w'] || this.keys[' ']);
    const flapPressed = flap && !this.prevFlap;
    this.prevFlap = flap;

    // VR controller input
    let vrLeft = false, vrRight = false, vrFlap = false, vrFlapPressed = false;
    try {
      const input = this.world.input;
      if (input) {
        const axes = (input as any).getAxesValues?.('ThumbstickX');
        if (axes && typeof axes === 'object') {
          const x = (axes as any).x ?? axes;
          if (typeof x === 'number') {
            if (x < -0.3) vrLeft = true;
            if (x > 0.3) vrRight = true;
          }
        }
        const trigger = (input as any).getButtonValue?.('Trigger');
        if (typeof trigger === 'number' && trigger > 0.5) vrFlap = true;
        const btnA = (input as any).getButtonValue?.('ButtonA');
        if (typeof btnA === 'number' && btnA > 0.5) vrFlap = true;
        const btnB = (input as any).getButtonValue?.('ButtonB');
        if (typeof btnB === 'number' && btnB > 0.5) {
          if (gameState.screen === 'playing') gameState.screen = 'paused';
        }
      }
    } catch {}

    game.setInput(
      left || vrLeft,
      right || vrRight,
      flap || vrFlap,
      flapPressed || (vrFlap && !this.prevFlap),
    );
  }
}

// Neon Joust VR — UI system (PanelUI management)
import { createSystem, World, PanelUI, PanelDocument, UIKit, ScreenSpace } from '@iwsdk/core';
import { gameState, ACHIEVEMENTS, COLOR_NAMES, GameMode, POWERUP_NAMES } from './game-state.js';
import { GameSystem } from './game-system.js';

type PanelName = 'menu' | 'hud' | 'pause' | 'results' | 'settings' | 'tutorial' | 'stats' | 'achievements';
const PANEL_CONFIGS: Record<PanelName, string> = {
  menu: './ui/menu.json',
  hud: './ui/hud.json',
  pause: './ui/pause.json',
  results: './ui/results.json',
  settings: './ui/settings.json',
  tutorial: './ui/tutorial.json',
  stats: './ui/stats.json',
  achievements: './ui/achievements.json',
};

const CONFIG_TO_NAME: Record<string, PanelName> = {};
for (const [n, c] of Object.entries(PANEL_CONFIGS)) CONFIG_TO_NAME[c] = n as PanelName;

function screenToPanel(screen: string): PanelName {
  if (screen === 'playing') return 'hud';
  if (screen === 'paused') return 'pause';
  if (screen === 'gameover') return 'results';
  return screen as PanelName;
}

export class UISystem extends createSystem({
  panels: { required: [PanelUI, PanelDocument] },
}) {

  private docs: Map<PanelName, any> = new Map();
  private panelEntities: Map<PanelName, any> = new Map();
  private activePanel: PanelName = 'menu';
  private prevScreen = '';
  private achPage = 0;

  init() {
    // Create all panel entities
    for (const [name, config] of Object.entries(PANEL_CONFIGS)) {
      const entity = this.world.createEntity();
      entity.addComponent(PanelUI, { config });
      if (name === 'hud') {
        entity.addComponent(ScreenSpace);
      }
    }

    // Listen for qualify events on the panels query
    this.queries.panels.subscribe('qualify', (entity) => {
      const config = entity.getValue(PanelUI, 'config') as string;
      const name = CONFIG_TO_NAME[config];
      if (!name) return;
      const doc = PanelDocument.data.document[entity.index] as any;
      if (!doc) return;
      this.docs.set(name, doc);
      this.panelEntities.set(name, entity);
      this.wirePanel(name, doc);
      // Show/hide based on current screen
      const vis = screenToPanel(gameState.screen) === name;
      (doc as any).setProperties?.({ visible: vis });
      // For non-active panels, hide via root
      const root = doc.children?.[0];
      if (root && !vis) {
        root.setProperties?.({ visibility: 'hidden' });
      }
    });
  }

  private findEl(doc: any, id: string): any {
    try { return doc.getElementById(id); } catch { return null; }
  }

  private wirePanel(name: PanelName, doc: any) {
    const findEl = (id: string) => this.findEl(doc, id);

    if (name === 'menu') {
      this.wireBtn(findEl('btn-arcade'), () => this.startMode('arcade'));
      this.wireBtn(findEl('btn-speed'), () => this.startMode('speed'));
      this.wireBtn(findEl('btn-zen'), () => this.startMode('zen'));
      this.wireBtn(findEl('btn-challenge'), () => this.startMode('challenge'));
      this.wireBtn(findEl('btn-settings'), () => { gameState.screen = 'settings'; });
      this.wireBtn(findEl('btn-tutorial'), () => { gameState.screen = 'tutorial'; });
      this.wireBtn(findEl('btn-stats'), () => { gameState.screen = 'stats'; });
      this.wireBtn(findEl('btn-achievements'), () => { gameState.screen = 'achievements'; });
    } else if (name === 'pause') {
      this.wireBtn(findEl('btn-resume'), () => { gameState.screen = 'playing'; });
      this.wireBtn(findEl('btn-quit'), () => { gameState.screen = 'menu'; });
    } else if (name === 'results') {
      this.wireBtn(findEl('btn-retry'), () => this.startMode(gameState.mode));
      this.wireBtn(findEl('btn-menu'), () => { gameState.screen = 'menu'; });
    } else if (name === 'settings') {
      this.wireBtn(findEl('btn-sound'), () => {
        gameState.soundEnabled = !gameState.soundEnabled;
        gameState.saveStats();
      });
      this.wireBtn(findEl('btn-music'), () => {
        gameState.musicEnabled = !gameState.musicEnabled;
        gameState.saveStats();
      });
      this.wireBtn(findEl('btn-color'), () => {
        gameState.colorScheme = (gameState.colorScheme + 1) % 4;
        gameState.saveStats();
      });
      this.wireBtn(findEl('btn-diff'), () => {
        const diffs: Array<'normal' | 'hard' | 'insane'> = ['normal', 'hard', 'insane'];
        const idx = diffs.indexOf(gameState.difficulty);
        gameState.difficulty = diffs[(idx + 1) % 3];
      });
      this.wireBtn(findEl('btn-back'), () => { gameState.screen = 'menu'; });
    } else if (name === 'tutorial') {
      this.wireBtn(findEl('btn-back'), () => { gameState.screen = 'menu'; });
    } else if (name === 'stats') {
      this.wireBtn(findEl('btn-back'), () => { gameState.screen = 'menu'; });
    } else if (name === 'achievements') {
      this.wireBtn(findEl('btn-back'), () => { gameState.screen = 'menu'; });
      this.wireBtn(findEl('btn-prev'), () => { this.achPage = Math.max(0, this.achPage - 1); });
      this.wireBtn(findEl('btn-next'), () => { this.achPage = Math.min(Math.floor((ACHIEVEMENTS.length - 1) / 5), this.achPage + 1); });
    }
  }

  private wireBtn(el: any, fn: () => void) {
    if (!el) return;
    el.addEventListener('click', fn);
  }

  private startMode(mode: string) {
    const game = ((this.world as any).getSystem(GameSystem) as GameSystem);
    if (game) game.startGame(mode);
  }

  update(_delta: number, _time: number) {
    const currentPanel = screenToPanel(gameState.screen);
    if (currentPanel !== this.activePanel) {
      // Hide old panel
      const oldDoc = this.docs.get(this.activePanel);
      if (oldDoc) {
        const root = oldDoc.children?.[0];
        if (root) root.setProperties?.({ visibility: 'hidden' });
      }
      // Show new panel
      const curDoc = this.docs.get(currentPanel);
      if (curDoc) {
        const root = curDoc.children?.[0];
        if (root) root.setProperties?.({ visibility: 'visible' });
      }
      this.activePanel = currentPanel;
    }
    this.updatePanelContent(currentPanel);
    this.prevScreen = gameState.screen;
  }

  private updatePanelContent(panel: PanelName) {
    const doc = this.docs.get(panel);
    if (!doc) return;
    const findEl = (id: string) => this.findEl(doc, id);

    if (panel === 'hud') {
      this.setText(findEl('txt-score'), `SCORE: ${gameState.score}`);
      this.setText(findEl('txt-wave'), `WAVE ${gameState.wave}`);
      this.setText(findEl('txt-lives'), `LIVES: ${gameState.lives}`);
      if (gameState.combo > 1) {
        this.setText(findEl('txt-combo'), `x${gameState.combo} COMBO`);
      } else {
        this.setText(findEl('txt-combo'), '');
      }
      if (gameState.mode === 'speed') {
        this.setText(findEl('txt-timer'), `TIME: ${Math.ceil(gameState.speedTimer)}s`);
      } else {
        this.setText(findEl('txt-timer'), '');
      }
      // Power-up indicator
      if (gameState.activePowerUp) {
        const name = POWERUP_NAMES[gameState.activePowerUp] ?? '';
        const secs = Math.ceil(gameState.powerUpTimer);
        this.setText(findEl('txt-powerup'), `${name} ${secs}s`);
      } else {
        this.setText(findEl('txt-powerup'), '');
      }
      // Wave announcement
      if (gameState.waveTransition && gameState.waveTransitionTimer > 1.0) {
        const bossMsg = gameState.bossWave ? 'BOSS WAVE' : `WAVE ${gameState.wave} START!`;
        const bonusMsg = gameState.waveBonus > 0 ? ` +${gameState.waveBonus}` : '';
        this.setText(findEl('txt-wave-announce'), bossMsg + bonusMsg);
      } else {
        this.setText(findEl('txt-wave-announce'), '');
      }
      // Boss HP indicator
      if (gameState.bossWave) {
        this.setText(findEl('txt-boss-hp'), this.getBossHpText());
      } else {
        this.setText(findEl('txt-boss-hp'), '');
      }
      // Kill streak
      if (gameState.killStreak >= 2) {
        this.setText(findEl('txt-streak'), `${gameState.killStreak}x AIR STREAK`);
      } else {
        this.setText(findEl('txt-streak'), '');
      }
      // Wind indicator
      if (Math.abs(gameState.windForce) > 0.3) {
        const dir = gameState.windForce > 0 ? '>>>' : '<<<';
        this.setText(findEl('txt-wind'), `WIND ${dir}`);
      } else {
        this.setText(findEl('txt-wind'), '');
      }
    } else if (panel === 'results') {
      this.setText(findEl('txt-final-score'), `SCORE: ${gameState.score}`);
      this.setText(findEl('txt-final-wave'), `WAVE: ${gameState.wave}`);
      this.setText(findEl('txt-final-kills'), `ENEMIES: ${gameState.killsThisGame}`);
      this.setText(findEl('txt-final-eggs'), `EGGS: ${gameState.eggsThisGame}`);
      this.setText(findEl('txt-final-combo'), `BEST COMBO: x${gameState.maxCombo}`);
      this.setText(findEl('txt-best'), `HIGH SCORE: ${gameState.bestScore}`);
      this.setText(findEl('txt-powerups'), `POWER-UPS: ${gameState.powerUpsThisGame}`);
      this.setText(findEl('txt-kill-streak'), `BEST STREAK: ${gameState.bestKillStreak}x`);
    } else if (panel === 'settings') {
      this.setText(findEl('txt-sound'), `SOUND: ${gameState.soundEnabled ? 'ON' : 'OFF'}`);
      this.setText(findEl('txt-music'), `MUSIC: ${gameState.musicEnabled ? 'ON' : 'OFF'}`);
      this.setText(findEl('txt-color'), `COLOR: ${COLOR_NAMES[gameState.colorScheme]}`);
      this.setText(findEl('txt-diff'), `DIFFICULTY: ${gameState.difficulty.toUpperCase()}`);
    } else if (panel === 'stats') {
      this.setText(findEl('txt-games'), `GAMES: ${gameState.totalGames}`);
      this.setText(findEl('txt-kills'), `ENEMIES DEFEATED: ${gameState.totalKillsAll}`);
      this.setText(findEl('txt-eggs'), `EGGS COLLECTED: ${gameState.totalEggsAll}`);
      this.setText(findEl('txt-waves'), `WAVES CLEARED: ${gameState.totalWavesAll}`);
      this.setText(findEl('txt-pteros'), `PTERODACTYLS: ${gameState.totalPterosAll}`);
      this.setText(findEl('txt-best-score'), `BEST SCORE: ${gameState.bestScore}`);
      this.setText(findEl('txt-best-wave'), `BEST WAVE: ${gameState.bestWave}`);
      this.setText(findEl('txt-best-combo'), `BEST COMBO: x${gameState.bestCombo}`);
    } else if (panel === 'achievements') {
      const start = this.achPage * 5;
      for (let i = 0; i < 5; i++) {
        const a = ACHIEVEMENTS[start + i];
        const el = findEl(`ach-${i}`);
        if (el && a) {
          const unlocked = gameState.achievements[a.id];
          this.setText(el, `${unlocked ? '[*]' : '[ ]'} ${a.name} - ${a.desc}`);
        } else if (el) {
          this.setText(el, '');
        }
      }
      this.setText(findEl('txt-page'), `${this.achPage + 1}/${Math.ceil(ACHIEVEMENTS.length / 5)}`);
      const unlocked = Object.keys(gameState.achievements).filter(k => gameState.achievements[k]).length;
      this.setText(findEl('txt-total'), `${unlocked}/${ACHIEVEMENTS.length} UNLOCKED`);
    }
  }

  private setText(el: any, text: string) {
    if (el) {
      try { el.setProperties({ content: text }); } catch {}
    }
  }

  private getBossHpText(): string {
    try {
      const game = ((this.world as any).getSystem(GameSystem) as GameSystem);
      if (!game) return '';
      const enemies = (game as any).enemies as any[];
      const dragon = enemies?.find((e: any) => e.type === 'dragon' && e.alive);
      if (dragon) {
        const filled = '#'.repeat(dragon.hp);
        const empty = '-'.repeat(dragon.maxHp - dragon.hp);
        return `DRAGON [${filled}${empty}]`;
      }
    } catch {}
    return '';
  }
}

